"""Migration of Meridian CRM 4.2 credit_hold_sweep.crms."""

from decimal import Decimal
from typing import Any


_ZERO = Decimal("0")
_EIGHT = Decimal("8")
_TEN = Decimal("10")


def _number(value: Any) -> Decimal:
    """Apply legacy NVL/numeric empty-value behavior using exact decimals."""
    if value is None:
        return _ZERO
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return _ZERO
    return Decimal(str(value))


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    """Run the nightly credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[Any, Decimal] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        acct_id = order.get("ACCT_ID")
        exposure_by_account[acct_id] = (
            exposure_by_account.get(acct_id, _ZERO)
            + _number(order.get("TOT_AMT"))
        )

    indexed_accounts = sorted(
        enumerate(new_accounts),
        key=lambda item: item[1].get("ACCT_ID"),
    )

    for _, account in indexed_accounts:
        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        acct_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(acct_id, _ZERO)
        credit_limit = _number(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if (
            exposure <= credit_limit * _EIGHT / _TEN
            and account.get("CRED_HOLD") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
